CustomField.formula:
TEXT(
  FLOOR(
    ( ( YEAR( End_Date__c ) - YEAR( Start_Date__c ) ) * 12 + 
      MONTH( End_Date__c ) - MONTH( Start_Date__c ) - 
      IF( DAY( End_Date__c ) < DAY( Start_Date__c ), 1, 0 ) 
    ) / 12
  )
) & " Years " & 
TEXT(
  MOD(
    ( YEAR( End_Date__c ) - YEAR( Start_Date__c ) ) * 12 + 
    MONTH( End_Date__c ) - MONTH( Start_Date__c ) - 
    IF( DAY( End_Date__c ) < DAY( Start_Date__c ), 1, 0 ),
    12
  )
) & " Months"
